const AUTO_HEADER = `// AUTO-GENERATED BY create-fullstack-feature
// DO NOT EDIT MANUALLY`;

/**
 * Idempotently register a feature reducer in Client/src/store/generated-reducers.ts.
 * @param {object} config
 * @param {string} [existingContents]
 * @returns {string}
 */
export function buildGeneratedReducers(config, existingContents) {
  const { camelPluralName: camelPlural, kebabPluralName: kebabPlural } =
    config.feature;

  const importLine = `import ${camelPlural}Reducer from "@/modules/${kebabPlural}/slices/${camelPlural}.slice";`;
  const entryLine = `  ${camelPlural}: ${camelPlural}Reducer,`;

  let content =
    existingContents && existingContents.trim().length > 0
      ? existingContents
      : defaultReducers();

  if (content.includes(entryLine)) {
    return content;
  }

  content = ensureImport(content, importLine);
  content = ensureObjectEntry(content, 'generatedReducers', entryLine);
  return content;
}

/**
 * Idempotently register a feature in Client/src/navigation/generated-dashboard-nav.ts.
 * @param {object} config
 * @param {string} [existingContents]
 * @returns {string}
 */
export function buildGeneratedDashboardNav(config, existingContents) {
  const { camelPluralName: camelPlural, kebabPluralName: kebabPlural } =
    config.feature;
  const enPlural = config.labels?.enPlural ?? config.feature.pluralName;

  let content =
    existingContents && existingContents.trim().length > 0
      ? existingContents
      : defaultDashboardNav();

  const hrefMarker = `href: "/dashboard/${kebabPlural}"`;
  if (content.includes(hrefMarker)) {
    return content;
  }

  content = ensureImport(content, 'import { Boxes } from "lucide-react";');

  const entry = `  {
    labelKey: "nav.${camelPlural}",
    label: ${JSON.stringify(enPlural)},
    href: "/dashboard/${kebabPlural}",
    icon: Boxes,
  },`;

  content = ensureArrayEntry(content, 'generatedDashboardNav', entry, hrefMarker);
  return content;
}

/**
 * @returns {string}
 */
function defaultReducers() {
  return `${AUTO_HEADER}

export const generatedReducers = {};
`;
}

/**
 * @returns {string}
 */
function defaultDashboardNav() {
  return `${AUTO_HEADER}

import type { LucideIcon } from "lucide-react";
import { Boxes } from "lucide-react";

export type DashboardNavItem = {
  labelKey: string;
  label: string;
  href: string;
  icon: LucideIcon;
};

export const generatedDashboardNav: DashboardNavItem[] = [];
`;
}

/**
 * @param {string} content
 * @param {string} importLine
 */
function ensureImport(content, importLine) {
  if (content.includes(importLine)) {
    return content;
  }

  const lines = content.split('\n');
  let lastImport = -1;
  for (let index = 0; index < lines.length; index += 1) {
    if (/^import\s/.test(lines[index])) {
      lastImport = index;
    }
  }

  if (lastImport === -1) {
    const headerEnd = content.indexOf('\n\n');
    if (headerEnd !== -1) {
      return `${content.slice(0, headerEnd)}\n\n${importLine}${content.slice(headerEnd)}`;
    }
    return `${importLine}\n${content}`;
  }

  lines.splice(lastImport + 1, 0, importLine);
  return lines.join('\n');
}

/**
 * @param {string} content
 * @param {string} objectName
 * @param {string} entryLine
 */
function ensureObjectEntry(content, objectName, entryLine) {
  const emptyPattern = new RegExp(`export const ${objectName} = \\{\\};`);
  if (emptyPattern.test(content)) {
    return content.replace(
      emptyPattern,
      `export const ${objectName} = {\n${entryLine}\n};`,
    );
  }

  const filledPattern = new RegExp(
    `(export const ${objectName} = \\{)([\\s\\S]*?)(\\n\\};)`,
  );
  return content.replace(filledPattern, (match, open, inner, close) => {
    const body = inner.replace(/\s+$/, '');
    return `${open}${body}\n${entryLine}${close}`;
  });
}

/**
 * @param {string} content
 * @param {string} arrayName
 * @param {string} entry
 * @param {string} marker
 */
function ensureArrayEntry(content, arrayName, entry, marker) {
  if (content.includes(marker)) {
    return content;
  }

  const emptyPattern = new RegExp(
    `export const ${arrayName}: DashboardNavItem\\[\\] = \\[\\];`,
  );
  if (emptyPattern.test(content)) {
    return content.replace(
      emptyPattern,
      `export const ${arrayName}: DashboardNavItem[] = [\n${entry}\n];`,
    );
  }

  const filledPattern = new RegExp(
    `(export const ${arrayName}: DashboardNavItem\\[\\] = \\[)([\\s\\S]*?)(\\n\\];)`,
  );
  return content.replace(filledPattern, (match, open, inner, close) => {
    const body = inner.replace(/\s+$/, '');
    return `${open}${body}\n${entry}${close}`;
  });
}
